// Нет воды в кадре: «לא זוהו מים באזור שסומן. כוונו את המצלמה לבריכה וסמנו את שטח המים.», «המשך» серая даже с галочкой.
// Красная зона — визуально, вручную. РУЧНАЯ СЦЕНА: камера iPhone на экран Mac с .qa/media/table-brown.png на весь экран →
// BANCI_SCENE=no-water (иначе пропуск). Мониторинг НЕ запускается.
import { by, skip, checkedFromValue } from '../../lib/appium.mjs';
import { openCameraStep, waitEnabled } from '../../lib/banci.mjs';

export const name = 'Шаг 2, нет воды: «לא זוהו מים באזור שסומן…», «המשך» серая даже с галочкой (ручная сцена BANCI_SCENE=no-water) #8dc640 @iphone @app @prod-safe';
const NO_WATER = 'לא זוהו מים באזור שסומן. כוונו את המצלמה לבריכה וסמנו את שטח המים.';

export default async function (app) {
  if (process.env.BANCI_SCENE !== 'no-water') skip('ручная сцена: открыть на Mac на весь экран .qa/media/table-brown.png, направить камеру iPhone и запустить с BANCI_SCENE=no-water');

  const water = await openCameraStep(app);
  await app.waitFor(by.contains('לא זוהו מים באזור שסומן'), { timeout: 20000, what: `подсказка «${NO_WATER}» (если её нет — проверить сцену)` });
  await app.waitFor(by.contains(NO_WATER), { timeout: 5000, what: `полный текст «${NO_WATER}»` });

  if (checkedFromValue(await water.attr('value')) !== true) await water.click();
  const next = await app.waitFor(by.exact('המשך', 'Button'), { what: '«המשך» на шаге 2' });
  await waitEnabled(next, false, { timeout: 5000, what: '«המשך» без воды в кадре, с галочкой' });
  await app.screenshot('8dc640-auto-no-water');
  await app.restart();
}
